DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.notify_news(uuid)'::regprocedure) INTO definition; definition:=replace(definition,'n.id,n.published_at FROM public.characters','n.id,public.game_now() FROM public.characters'); definition:=replace(definition,'nf.world_at>n.published_at-','nf.world_at>public.game_now()-'); EXECUTE definition; SELECT pg_get_functiondef('public.news_state()'::regprocedure) INTO definition; definition:=replace(definition,'ORDER BY n.published_at DESC LIMIT 500','ORDER BY n.published_at DESC'); EXECUTE definition; END $$;